javas.java:

int def scoreOperatingYears(int:operatingYears) {
    if (operatingYears >= 10) {
        return 15;
    } else if (operatingYears >= 5) {
        return 12;
    } else if (operatingYears >= 3) {
        return 8;
    } else if (operatingYears >= 1) {
        return 4;
    } else {
        return 0;
    }
}


int def scoreRevenue(double:annualRevenue) {
    if (annualRevenue >= 100000000.0) {
        return 20;
    } else if (annualRevenue >= 50000000.0) {
        return 16;
    } else if (annualRevenue >= 20000000.0) {
        return 12;
    } else if (annualRevenue >= 5000000.0) {
        return 7;
    } else {
        return 3;
    }
}


int def scoreTaxCredit(str:taxCreditLevel, double:annualTaxAmount) {
    if (taxCreditLevel == "A") {
        if (annualTaxAmount >= 1000000.0) {
            return 20;
        } else if (annualTaxAmount >= 300000.0) {
            return 17;
        } else {
            return 14;
        }
    } else if (taxCreditLevel == "B") {
        if (annualTaxAmount >= 1000000.0) {
            return 15;
        } else if (annualTaxAmount >= 300000.0) {
            return 13;
        } else {
            return 10;
        }
    } else if (taxCreditLevel == "M") {
        if (annualTaxAmount >= 300000.0) {
            return 10;
        } else if (annualTaxAmount >= 100000.0) {
            return 8;
        } else {
            return 6;
        }
    } else if (taxCreditLevel == "C") {
        return 4;
    } else {
        return 0;
    }
}


int def scoreBankFlow(double:bankFlowAnnual, double:annualRevenue) {
    if (annualRevenue <= 0.0) {
        return 0;
    }
    if (bankFlowAnnual * 10 >= annualRevenue * 12) {
        return 15;
    } else if (bankFlowAnnual >= annualRevenue) {
        return 12;
    } else if (bankFlowAnnual * 10 >= annualRevenue * 8) {
        return 8;
    } else if (bankFlowAnnual * 10 >= annualRevenue * 5) {
        return 4;
    } else {
        return 0;
    }
}


int def scoreDebtRatio(int:debtRatio) {
    if (debtRatio <= 40) {
        return 15;
    } else if (debtRatio <= 55) {
        return 12;
    } else if (debtRatio <= 70) {
        return 8;
    } else if (debtRatio <= 80) {
        return 4;
    } else {
        return 0;
    }
}


int def scoreCreditRecord(int:overdueCount, boolean:hasJudicialRecord) {
    if (hasJudicialRecord) {
        return 0;
    }
    if (overdueCount == 0) {
        return 15;
    } else if (overdueCount <= 2) {
        return 11;
    } else if (overdueCount <= 4) {
        return 6;
    } else {
        return 0;
    }
}


str def creditRating(int:totalScore) {
    if (totalScore >= 85) {
        return "A";
    } else if (totalScore >= 75) {
        return "B";
    } else if (totalScore >= 60) {
        return "C";
    } else {
        return "D";
    }
}


str def approveDecision(int:totalScore) {
    if (totalScore >= 75) {
        return "APPROVE";
    } else if (totalScore >= 60) {
        return "MANUAL_REVIEW";
    } else {
        return "REJECT";
    }
}


double def taxMultiplier(str:taxCreditLevel, int:totalScore) {
    if (taxCreditLevel == "A") {
        if (totalScore >= 85) {
            return 9.0;
        } else if (totalScore >= 75) {
            return 7.0;
        } else {
            return 4.0;
        }
    } else if (taxCreditLevel == "B") {
        if (totalScore >= 85) {
            return 6.0;
        } else if (totalScore >= 75) {
            return 4.5;
        } else {
            return 2.5;
        }
    } else if (taxCreditLevel == "M") {
        if (totalScore >= 75) {
            return 3.0;
        } else if (totalScore >= 60) {
            return 2.0;
        } else {
            return 1.0;
        }
    } else {
        return 0.0;
    }
}


double def interestRate(str:creditRating) {
    if (creditRating == "A") {
        return 0.0345;
    } else if (creditRating == "B") {
        return 0.0385;
    } else if (creditRating == "C") {
        return 0.0435;
    } else {
        return 0.0;
    }
}
